def choose_move(observation):
    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def clamp_step(a, b):
        return [sign(a - sx), sign(b - sy)]

    def safe_pos(v, default=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def nearest(items):
        best = None
        best_d = None
        for item in items or []:
            p = safe_pos(item)
            if p is None:
                continue
            d = abs(p[0] - sx) + abs(p[1] - sy)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def farthest(items):
        best = None
        best_d = None
        for item in items or []:
            p = safe_pos(item)
            if p is None:
                continue
            d = abs(p[0] - sx) + abs(p[1] - sy)
            if best is None or d > best_d:
                best = p
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sp = safe_pos(observation.get("self_position"), (0, 0))
    sx, sy = sp[0], sp[1]
    op = safe_pos(observation.get("opponent_position"), (sx, sy))
    ox, oy = op[0], op[1]
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            target = (ox, oy)
            return clamp_step(target[0], target[1])
        corners = [(0, 0)]
        if gh:
            corners.append((0, gh - 1))
        if gw:
            corners.append((gw - 1, 0))
        if gw and gh:
            corners.append((gw - 1, gh - 1))
        target = farthest(corners) or (sx, sy)
        return clamp_step(target[0], target[1])

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = nearest(targets)
        if target is None:
            center = (gw // 2 if gw else sx, gh // 2 if gh else sy)
            return clamp_step(center[0], center[1])
        return clamp_step(target[0], target[1])

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = nearest(resources)
    if target is not None:
        return clamp_step(target[0], target[1])

    # Fallback: move toward opponent only if it may create interaction; otherwise hold center.
    if ox != sx or oy != sy:
        if abs(ox - sx) + abs(oy - sy) <= 2:
            return clamp_step(ox, oy)
    center = (gw // 2 if gw else sx, gh // 2 if gh else sy)
    return clamp_step(center[0], center[1])

